@extends('definitions.layout') @section('content')<div class="bar"><h1>کالاها و خدمات</h1><a class="btn" href="{{ route('definitions.goods.create') }}">کالا/خدمت جدید</a></div><div class="card"><table><tr><th>کد</th><th>نام</th><th>نوع</th><th>دسته</th><th>قابلیت‌ها</th><th>وضعیت</th><th></th></tr>@foreach($goods as $g)<tr><td>{{ $g->code }}</td><td>{{ $g->name }}</td><td>{{ $g->item_type==='service'?'خدمت':'کالا' }}</td><td>{{ $g->category->name }}</td><td>{{ $g->purchasable?'خرید ':'' }}{{ $g->producible?'تولید ':'' }}{{ $g->sellable?'فروش':'' }}</td><td>{{ $g->is_active?'فعال':'غیرفعال' }}</td><td class="actions"><a href="{{ route('definitions.goods.edit',$g) }}">ویرایش</a>@if($g->is_active)<form method="POST" action="{{ route('definitions.goods.deactivate',$g) }}">@csrf @method('PATCH')<button>غیرفعال</button></form>@else<form method="POST" action="{{ route('definitions.goods.activate',$g) }}">@csrf @method('PATCH')<button>فعال</button></form>@endif</td></tr>@endforeach</table>{{ $goods->links() }}</div>@endsection